"use client";

import { useState } from "react";
import {
  FileText,
  Sparkles,
  ChevronDown,
} from "lucide-react";

const contentTypes = [
  "General Post",
  "Social Media Post",
  "Advertisement",
  "Tourism Content",
  "Website Content",
  "Educational Material",
  "Festival Content",
  "Food & Cuisine",
  "Traditional Arts",
  "Customs & Traditions",
];

const targetAudiences = [
  "International Audience",
  "International Students",
  "Tourists",
  "General Public",
  "Academic Audience",
];

type EvaluationFormProps = {
  onContentChange?: (content: string) => void;
};

export default function EvaluationForm({
  onContentChange,
}: EvaluationFormProps) {
  const [content, setContent] = useState("");
  const [contentType, setContentType] = useState("General Post");
  const [targetAudience, setTargetAudience] =
    useState("International Audience");

  const maxLength = 2000;

  const handleContentChange = (
    e: React.ChangeEvent<HTMLTextAreaElement>
  ) => {
    const value = e.target.value.slice(0, maxLength);

    setContent(value);
    onContentChange?.(value);
  };

  return (
    <section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm">
      {/* Header */}
      <div className="mb-6 flex items-center gap-3">
        <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-blue-50">
          <FileText className="h-5 w-5 text-blue-600" />
        </div>

        <div>
          <h2 className="text-xl font-bold text-slate-900">
            Evaluate Chinese Cultural Content
          </h2>

          <p className="mt-1 text-sm text-slate-500">
            Enter Chinese cultural related content for AI-powered evaluation.
          </p>
        </div>
      </div>

      {/* Textarea */}
      <div>
        <textarea
          value={content}
          onChange={handleContentChange}
          placeholder="Enter the content you want to evaluate..."
          className="min-h-[180px] w-full resize-none rounded-xl border border-slate-200 bg-slate-50 p-4 text-sm text-slate-900 outline-none transition focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
        />

        <div className="mt-2 flex items-center justify-between text-xs text-slate-500">
          <span>
            Example: Chinese people always drink tea. It is a simple and
            traditional habit.
          </span>

          <span>
            {content.length}/{maxLength}
          </span>
        </div>
      </div>

      {/* Select Fields */}
      <div className="mt-6 grid gap-5 md:grid-cols-2">
        {/* Content Type */}
        <div>
          <label className="mb-2 block text-sm font-semibold text-slate-800">
            Content Type
          </label>

          <div className="relative">
            <select
              value={contentType}
              onChange={(e) => setContentType(e.target.value)}
              className="w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            >
              {contentTypes.map((type) => (
                <option key={type} value={type}>
                  {type}
                </option>
              ))}
            </select>

            <ChevronDown className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          </div>
        </div>

        {/* Target Audience */}
        <div>
          <label className="mb-2 block text-sm font-semibold text-slate-800">
            Target Audience
          </label>

          <div className="relative">
            <select
              value={targetAudience}
              onChange={(e) => setTargetAudience(e.target.value)}
              className="w-full appearance-none rounded-xl border border-slate-200 bg-white px-4 py-3 text-sm text-slate-700 outline-none focus:border-blue-500 focus:ring-2 focus:ring-blue-100"
            >
              {targetAudiences.map((audience) => (
                <option key={audience} value={audience}>
                  {audience}
                </option>
              ))}
            </select>

            <ChevronDown className="pointer-events-none absolute right-4 top-1/2 h-4 w-4 -translate-y-1/2 text-slate-400" />
          </div>
        </div>
      </div>

      {/* Evaluate Button */}
      <button
        type="button"
        className="mt-6 flex w-full items-center justify-center gap-2 rounded-xl bg-blue-600 px-5 py-3.5 text-sm font-semibold text-white transition hover:bg-blue-700"
      >
        <Sparkles className="h-4 w-4" />
        Evaluate Content
      </button>
    </section>
  );
}